package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for Node.previousSibling()
 */
public class Node_previousSibling_TriageGen2Test {

    private Document doc;

    @Before
    public void setUp() {
        doc = Document.createShell("");
    }

    /**
     * Test case where the node is the first sibling (index 0).
     * Expected: returns null.
     */
    @Test
    public void testPreviousSibling_FirstSiblingReturnsNull() {
        Element parent = doc.body();
        Element first = parent.appendElement("div");
        Element second = parent.appendElement("span");

        // first is at index 0
        assertNull("The first sibling should have no previous sibling", first.previousSibling());
    }

    /**
     * Test case where the node is not the first sibling (index > 0).
     * Expected: returns the preceding sibling.
     */
    @Test
    public void testPreviousSibling_MiddleSiblingReturnsPreceding() {
        Element parent = doc.body();
        Element first = parent.appendElement("div");
        Element second = parent.appendElement("span");
        Element third = parent.appendElement("p");

        // second is at index 1, previous should be first
        assertEquals("The previous sibling of the second node should be the first node", first, second.previousSibling());

        // third is at index 2, previous should be second
        assertEquals("The previous sibling of the third node should be the second node", second, third.previousSibling());
    }

    /**
     * Test case where the node is the last sibling.
     * Expected: returns the preceding sibling.
     */
    @Test
    public void testPreviousSibling_LastSiblingReturnsPreceding() {
        Element parent = doc.body();
        Element first = parent.appendElement("div");
        Element second = parent.appendElement("span");

        assertEquals(first, second.previousSibling());
    }

    /**
     * Test case where the node has no parent.
     * Note: The implementation relies on parentNode.childNodes. 
     * If parentNode is null, it will throw a NullPointerException.
     */
    @Test(expected = NullPointerException.class)
    public void testPreviousSibling_NoParentThrowsException() {
        Element orphan = new Element("");
        // orphan.parentNode() is null
        orphan.previousSibling();
    }

    /**
     * Test case to ensure siblingIndex dependency.
     * This tests the branch where index is calculated via siblingIndex().
     */
    @Test
    public void testPreviousSibling_WithMultipleChildren() {
        Element parent = doc.body();
        List<Element> children = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            children.add(parent.appendElement("div").attr("id", String.valueOf(i)));
        }

        for (int i = 1; i < 5; i++) {
            assertEquals("Sibling at index " + i + " should have sibling at index " + (i - 1),
                    children.get(i - 1), children.get(i).previousSibling());
        }
    }
}
